function getSpellsForWeapon(arme) {
  if (!arme) return [];
  const base = SPELLS[arme.weaponStyle] || [];
  const unique = arme.id && UNIQUE_SPELLS[arme.id] ? [UNIQUE_SPELLS[arme.id]] : [];
  return [...base, ...unique];
}

