// Pity counter: après X combats sans rare+, drop garanti
const PITY_THRESHOLD = 8;

function rollLoot(zoneKey, pityCount) {
  const table = DROP_TABLES[zoneKey] || DROP_TABLES.plaine;
  const drops = [];
  // Roll each item independently
  for (const entry of table) {
    if (Math.random() < entry.chance) {
      const item = ITEMS_DB[entry.id];
      if (item) drops.push({ ...item, uid: uid() });
    }
  }
  // Pity: force un rare si trop de combats sans rien de bien
  if (pityCount >= PITY_THRESHOLD && drops.filter(d => d.rarity !== "commun").length === 0) {
    const rarePool = table.filter(e => ITEMS_DB[e.id]?.rarity === "rare");
    if (rarePool.length > 0) {
      const pick = rarePool[Math.floor(Math.random() * rarePool.length)];
      drops.push({ ...ITEMS_DB[pick.id], uid: uid() });
    }
  }
  // Toujours au moins 1 objet (potion commun sinon)
  if (drops.length === 0) {
    drops.push({ ...ITEMS_DB["potion_soin"], uid: uid() });
  }
  return drops.slice(0, 3);
}

