const XP_TABLE = [0,60,140,260,420,640,920,1260,1700,2300,3000,3900,5000,6400,8200];
function xpNeeded(lvl) { return XP_TABLE[Math.min(lvl, XP_TABLE.length-1)] || 9999; }

// ============================================================
// HELPERS
// ============================================================
function uid() { return Math.random().toString(36).slice(2) + Date.now().toString(36); }

// ============================================================
// CHARACTERISTICS SYSTEM
// ============================================================
const CARAC_DEF = {
  force:       { label:"Force",        emoji:"⚔️", color:"#f87171", desc:"Dégâts physiques (+2/pt)" },
  intelligence:{ label:"Intelligence", emoji:"🔮", color:"#a855f7", desc:"Dégâts magiques (+2/pt) + Mana (+5/pt)" },
  agilite:     { label:"Agilité",      emoji:"💨", color:"#4ade80", desc:"Esquive (+1%/pt) + Critique (+0.5%/pt)" },
  vitalite:    { label:"Vitalité",     emoji:"❤️", color:"#f43f5e", desc:"HP max (+10/pt)" },
  chance:      { label:"Chance",       emoji:"🍀", color:"#f59e0b", desc:"Qualité de drop (+0.5%/pt)" },
  res_phys:    { label:"Rés. Physique",emoji:"🛡️", color:"#60a5fa", desc:"Réduit dégâts physiques (-1%/pt, max 50%)" },
  res_magie:   { label:"Rés. Magique", emoji:"✨", color:"#c084fc", desc:"Réduit dégâts magiques (-1%/pt, max 50%)" },
};

function getCaracIcon(key, size=18) {
  const ludo = CARAC_LUDO_ICONS[key];
  if (ludo) return <img src={ludo} width={size} height={size} style={{objectFit:"contain", verticalAlign:"middle", display:"inline-block"}}/>;
  if (key === "vitalite") return <StatIcon type="hp" size={size}/>;
  return <span style={{color:CARAC_DEF[key]?.color}}>{CARAC_DEF[key]?.emoji}</span>;
}

// Icônes SVG inline pour les stats de combat (def_phys, def_magie, hp, mana, etc.)
// atk_phys → icône Ludo "force", atk_magie → icône Ludo "intelligence"
function StatIcon({ type, size=14 }) {
  const s = size;
  // Pour atk_phys et atk_magie, on réutilise les vraies icônes Ludo
  if (type === "atk_phys")  return <img src={CARAC_LUDO_ICONS.force}        width={s} height={s} style={{objectFit:"contain",verticalAlign:"middle",display:"inline-block"}}/>;
  if (type === "atk_magie") return <img src={CARAC_LUDO_ICONS.intelligence} width={s} height={s} style={{objectFit:"contain",verticalAlign:"middle",display:"inline-block"}}/>;
  const icons = {
    def_phys: (
      <svg width={s} height={s} viewBox="0 0 16 16" style={{verticalAlign:"middle",display:"inline-block"}}>
        <path d="M8 2 L14 5 L14 9 Q14 13 8 15 Q2 13 2 9 L2 5 Z" fill="none" stroke="#60a5fa" strokeWidth="1.8" strokeLinejoin="round"/>
        <line x1="8" y1="5" x2="8" y2="11" stroke="#60a5fa" strokeWidth="1.2" opacity="0.7"/>
      </svg>
    ),
    def_magie: (
      <svg width={s} height={s} viewBox="0 0 16 16" style={{verticalAlign:"middle",display:"inline-block"}}>
        <path d="M8 2 L14 5 L14 9 Q14 13 8 15 Q2 13 2 9 L2 5 Z" fill="none" stroke="#c084fc" strokeWidth="1.8" strokeLinejoin="round"/>
        <circle cx="8" cy="8.5" r="2" fill="none" stroke="#c084fc" strokeWidth="1.2"/>
        <circle cx="8" cy="8.5" r="0.8" fill="#c084fc"/>
      </svg>
    ),
    hp: (
      <svg width={s} height={s} viewBox="0 0 16 16" style={{verticalAlign:"middle",display:"inline-block"}}>
        <path d="M8 13 C8 13 2 9 2 5.5 C2 3.5 3.5 2 5.5 2 C6.8 2 7.8 2.7 8 3.5 C8.2 2.7 9.2 2 10.5 2 C12.5 2 14 3.5 14 5.5 C14 9 8 13 8 13Z" fill="#f43f5e" stroke="#f43f5e" strokeWidth="0.5"/>
      </svg>
    ),
    mana: (
      <svg width={s} height={s} viewBox="0 0 16 16" style={{verticalAlign:"middle",display:"inline-block"}}>
        <ellipse cx="8" cy="10" rx="4" ry="5" fill="none" stroke="#38bdf8" strokeWidth="1.5"/>
        <path d="M6 6 Q8 2 10 6" fill="none" stroke="#38bdf8" strokeWidth="1.5" strokeLinecap="round"/>
        <ellipse cx="8" cy="10" rx="1.5" ry="2" fill="#38bdf8" opacity="0.7"/>
      </svg>
    ),
    pa: (
      <svg width={s} height={s} viewBox="0 0 16 16" style={{verticalAlign:"middle",display:"inline-block"}}>
        <circle cx="8" cy="8" r="6.5" fill="none" stroke="#fbbf24" strokeWidth="1.5"/>
        <text x="8" y="11.5" textAnchor="middle" fontSize="8" fontWeight="bold" fill="#fbbf24" fontFamily="sans-serif">PA</text>
      </svg>
    ),
    critique: (
      <svg width={s} height={s} viewBox="0 0 16 16" style={{verticalAlign:"middle",display:"inline-block"}}>
        <path d="M3 8 Q8 2 13 8" fill="none" stroke="#4ade80" strokeWidth="1.8" strokeLinecap="round"/>
        <path d="M13 8 L10 6 M13 8 L11 10.5" stroke="#4ade80" strokeWidth="1.5" strokeLinecap="round"/>
        <circle cx="5" cy="11" r="1.5" fill="#4ade80" opacity="0.6"/>
      </svg>
    ),
  };
  if (icons[type]) return icons[type];
  // Fallback sur getCaracIcon pour les caracs classiques
  return getCaracIcon(type, size);
}

function initCaracs() {
  return { force:0, intelligence:0, agilite:0, vitalite:0, chance:0, res_phys:0, res_magie:0 };
}

function calcStats(player) {
  const eq = player.equipped;
  const slots = ["chapeau","cape","plastron","gants","ceinture","jambieres","anneau","amulette","arme","bouclier","relique1","relique2","relique3","relique4"];
  let eqAtkPhys=0, eqAtkMagie=0, eqDefPhys=0, eqDefMagie=0, eqHp=0, eqDefMalus=0;
  // Bonus de caracs venant des items
  let itemCarac = { force:0, intelligence:0, agilite:0, vitalite:0, chance:0, res_phys:0, res_magie:0 };
  for (const s of slots) {
    const it = eq[s];
    if (!it) continue;
    eqAtkPhys  += (it.atk_phys  || it.atk || 0); // compat ancien format
    eqAtkMagie += (it.atk_magie || 0);
    eqDefPhys  += (it.def_phys  || it.def || 0);
    eqDefMagie += (it.def_magie || 0);
    eqHp       += (it.hp || 0);
    if (it.def_phys_malus) eqDefMalus += it.def_phys_malus;
    if (it.def_malus)      eqDefMalus += it.def_malus; // compat
    if (it.carac) {
      for (const [k,v] of Object.entries(it.carac)) itemCarac[k] = (itemCarac[k]||0) + v;
    }
  }
  const base = player.caracs || initCaracs();
  // Total caracs = player + items
  const c = {};
  for (const k of Object.keys(itemCarac)) c[k] = (base[k]||0) + (itemCarac[k]||0);

  const atkPhys  = player.baseAtk + eqAtkPhys  + (c.force * 2);
  const atkMagie = eqAtkMagie + (c.intelligence * 2);
  const defPhys  = Math.max(0, player.baseDef + eqDefPhys - eqDefMalus);
  const defMagie = Math.max(0, eqDefMagie);
  const maxHpBonus = eqHp + (c.vitalite * 10) + ((player.level-1) * 10);
  const manaMax  = 30 + (c.intelligence * 5);
  const esquive  = Math.min(40, c.agilite * 1);
  const critique = Math.min(50, 10 + c.agilite * 0.5);
  const resPhys  = Math.min(50, (base.res_phys||0) + (itemCarac.res_phys||0));
  const resMagie = Math.min(50, (base.res_magie||0) + (itemCarac.res_magie||0));
  const dropBonus = c.chance * 0.5;
  let finalStats = { atkPhys, atkMagie, defPhys, defMagie, maxHpBonus, manaMax, esquive, critique, resPhys, resMagie, dropBonus, itemCarac };
  // Appliquer les bonus de set
  finalStats = applySetBonuses(finalStats, player.equipped);
  return finalStats;
}

function isTwoHanded(item) { return item?.twoHanded === true; }

function initEquipped() {
  return { chapeau:null,cape:null,plastron:null,gants:null,ceinture:null,jambieres:null,anneau:null,amulette:null,arme:null,bouclier:null,relique1:null,relique2:null,relique3:null,relique4:null };
}

function initPlayer() {
  return {
    level:1, xp:0, hp:100, baseHp:100, baseAtk:8, baseDef:3, gold:50,
    mana:30, caracs: initCaracs(), caracPoints: 0,
    inventory:[], resources:{}, equipped: initEquipped(),
    skills:{ forge:0, alchimie:0, joaillerie:0, exploration:0 },
    pityCount:0,
  };
}

// ============================================================
// COLORS
// ============================================================
const RC = { commun:"#aaa", rare:"#4a9eff", epique:"#a855f7", legendaire:"#f59e0b", unique:"#ff8c00", relique:"#ff4d4d" };
const RB = { commun:"#444", rare:"#4a9eff", epique:"#a855f7", legendaire:"#f59e0b", unique:"#ff8c00", relique:"#ff4d4d" };

// ============================================================
// SMALL COMPONENTS
// ============================================================
function HpBar({ current, max }) {
  const pct = Math.max(0, Math.min(100, (current/max)*100));
  return (
    <div style={{ background:"#0d0d1a", borderRadius:5, overflow:"hidden", height:8, width:"100%" }}>
      <div style={{ width:`${pct}%`, height:"100%", background: pct>50?"#22c55e":pct>25?"#eab308":"#ef4444", transition:"width 0.3s" }} />
    </div>
  );
}

function XpBar({ xp, level }) {
  const pct = Math.min(100,(xp/xpNeeded(level))*100);
  return (
    <div style={{ background:"#0d0d1a", borderRadius:5, overflow:"hidden", height:6, width:"100%" }}>
      <div style={{ width:`${pct}%`, height:"100%", background:"linear-gradient(90deg,#7c3aed,#a855f7)", transition:"width 0.4s" }} />
    </div>
  );
}

function SkillBar({ val }) {
  return (
    <div style={{ background:"#0d0d1a", borderRadius:4, overflow:"hidden", height:5, flex:1 }}>
      <div style={{ width:`${val}%`, height:"100%", background:"#7c3aed", transition:"width 0.3s" }} />
    </div>
  );
}

function Btn({ onClick, disabled, color="#7c3aed", children, style={} }) {
  return (
    <button onClick={onClick} disabled={disabled} style={{
      background: disabled ? "#2d2d4e" : color, color: disabled?"#555":"#fff",
      border:"none", borderRadius:6, padding:"6px 12px", fontWeight:700, fontSize:12,
      cursor: disabled?"not-allowed":"pointer", ...style,
    }}>{children}</button>
  );
}

// ============================================================
// ITEM SVG ICONS
// Règle : silhouette simple + couleur dominante = lisible à 28px
// Casques  → demi-sphère + garde-joues
// Armures  → cuirasse avec épaulières (pas de t-shirt!)
// Bottes   → botte de chevalier avec talon
// Capes    → triangle avec col
// Ceintures→ boucle rectangulaire
// Anneaux  → cercle + gemme
// Armes    → forme propre à chaque type
// Boucliers→ écu pointu en bas
// Potions  → flacon avec liquide coloré
// Reliques → losange avec symbole intérieur
// Couleurs : cuir=#8B6040  fer=#9a9aaa  mithril=#88ccff  ombre=#a855f7  légendaire=#f59e0b
// ============================================================

// Helper : icône générique par matériau pour éviter la répétition
function HelmIcon({body, visor="#222", plume=null, glow=null}) {
  return (
    <svg viewBox="0 0 32 32" width="28" height="28">
      {/* calotte */}
      <path d="M7 20 Q7 8 16 6 Q25 8 25 20 Z" fill={body} stroke="rgba(0,0,0,0.4)" strokeWidth="1.5"/>
      {/* garde-joues */}
      <rect x="6" y="19" width="20" height="5" rx="2" fill={body} stroke="rgba(0,0,0,0.4)" strokeWidth="1.2"/>
      {/* visière */}
      <rect x="11" y="21" width="10" height="3" rx="1" fill={visor}/>
      {/* reflet */}
      <path d="M10 11 Q12 8 15 9" stroke="rgba(255,255,255,0.25)" strokeWidth="1.5" fill="none"/>
      {plume && <line x1="16" y1="6" x2="16" y2="1" stroke={plume} strokeWidth="2.5" strokeLinecap="round"/>}
      {glow && <path d="M7 20 Q7 8 16 6 Q25 8 25 20 Z" fill={glow} opacity="0.18"/>}
    </svg>
  );
}

function ChestIcon({main, stripe=null, glow=null, rivets=false}) {
  return (
    <svg viewBox="0 0 32 32" width="28" height="28">
      {/* épaulières gauche + droite */}
      <ellipse cx="8"  cy="9" rx="5" ry="4" fill={main} stroke="rgba(0,0,0,0.4)" strokeWidth="1.2"/>
      <ellipse cx="24" cy="9" rx="5" ry="4" fill={main} stroke="rgba(0,0,0,0.4)" strokeWidth="1.2"/>
      {/* torse cuirasse */}
      <path d="M8 11 L8 25 Q8 28 16 28 Q24 28 24 25 L24 11 Q20 8 16 8 Q12 8 8 11Z" fill={main} stroke="rgba(0,0,0,0.4)" strokeWidth="1.5"/>
      {/* ligne centrale */}
      <line x1="16" y1="9" x2="16" y2="27" stroke="rgba(0,0,0,0.3)" strokeWidth="1.5"/>
      {/* nervure pectorale */}
      <path d="M9 16 Q16 19 23 16" stroke="rgba(0,0,0,0.25)" strokeWidth="1.2" fill="none"/>
      {rivets && <>
        <circle cx="10" cy="12" r="1.2" fill="rgba(255,255,255,0.3)"/>
        <circle cx="22" cy="12" r="1.2" fill="rgba(255,255,255,0.3)"/>
      </>}
      {stripe && <line x1="9" y1="20" x2="23" y2="20" stroke={stripe} strokeWidth="1.5"/>}
      {glow && <path d="M8 11 L8 25 Q8 28 16 28 Q24 28 24 25 L24 11 Q20 8 16 8 Q12 8 8 11Z" fill={glow} opacity="0.2"/>}
    </svg>
  );
}

function BootIcon({main, sole="#222", glow=null}) {
  return (
    <svg viewBox="0 0 32 32" width="28" height="28">
      {/* tige de la botte */}
      <path d="M10 5 L10 20 Q10 22 12 22 L20 22 L20 19 L13 19 L13 5 Z" fill={main} stroke="rgba(0,0,0,0.4)" strokeWidth="1.5"/>
      {/* pied */}
      <path d="M10 20 Q10 26 14 26 L22 26 L22 23 L13 23 L13 20 Z" fill={main} stroke="rgba(0,0,0,0.4)" strokeWidth="1.2"/>
      {/* semelle */}
      <rect x="10" y="25" width="13" height="3" rx="1.5" fill={sole}/>
      {/* lacet/sangle décorative */}
      <line x1="10" y1="13" x2="13" y2="13" stroke="rgba(0,0,0,0.3)" strokeWidth="1.5"/>
      <line x1="10" y1="17" x2="13" y2="17" stroke="rgba(0,0,0,0.3)" strokeWidth="1.5"/>
      {glow && <path d="M10 5 L10 20 Q10 22 12 22 L20 22 L20 19 L13 19 L13 5 Z" fill={glow} opacity="0.25"/>}
    </svg>
  );
}

function CapeIcon({main, clasp=null, rune=null}) {
  return (
    <svg viewBox="0 0 32 32" width="28" height="28">
      <path d="M9 5 Q16 3 23 5 L27 29 Q16 24 5 29 Z" fill={main} stroke="rgba(0,0,0,0.4)" strokeWidth="1.5"/>
      <path d="M9 5 Q16 8 23 5" stroke="rgba(0,0,0,0.3)" strokeWidth="2" fill="none"/>
      <line x1="16" y1="7" x2="16" y2="27" stroke="rgba(0,0,0,0.2)" strokeWidth="1"/>
      {clasp && <circle cx="16" cy="6" r="2.5" fill={clasp} stroke="rgba(0,0,0,0.4)" strokeWidth="1"/>}
      {rune  && <path d="M12 15 L16 11 L20 15 L16 19 Z" fill={rune} opacity="0.7"/>}
    </svg>
  );
}

function BeltIcon({main, buckle, gem=null}) {
  return (
    <svg viewBox="0 0 32 32" width="28" height="28">
      <rect x="3" y="13" width="26" height="6" rx="3" fill={main} stroke="rgba(0,0,0,0.4)" strokeWidth="1.5"/>
      <rect x="11.5" y="11" width="9" height="10" rx="1.5" fill={buckle} stroke="rgba(0,0,0,0.4)" strokeWidth="1.5"/>
      <line x1="16" y1="12" x2="16" y2="20" stroke="rgba(0,0,0,0.3)" strokeWidth="1.5"/>
      <line x1="12" y1="16" x2="20" y2="16" stroke="rgba(0,0,0,0.3)" strokeWidth="1.5"/>
      {gem && <circle cx="16" cy="16" r="2.5" fill={gem}/>}
    </svg>
  );
}

function RingIcon({band, gem, gemHighlight=null}) {
  return (
    <svg viewBox="0 0 32 32" width="28" height="28">
      <circle cx="16" cy="19" r="8" stroke={band} strokeWidth="3" fill="none"/>
      <circle cx="16" cy="19" r="4.5" stroke={band} strokeWidth="1.5" fill="none"/>
      <polygon points="16,11 19,15 16,13.5 13,15" fill={band}/>
      <circle cx="16" cy="11" r="3" fill={gem} stroke="rgba(0,0,0,0.3)" strokeWidth="1"/>
      {gemHighlight && <circle cx="15" cy="10" r="1" fill={gemHighlight} opacity="0.7"/>}
    </svg>
  );
}

function ShieldIcon({main, emblem=null, glow=null}) {
  return (
    <svg viewBox="0 0 32 32" width="28" height="28">
      <path d="M16 4 L26 8 L26 18 Q26 26 16 29 Q6 26 6 18 L6 8 Z" fill={main} stroke="rgba(0,0,0,0.4)" strokeWidth="1.8"/>
      <path d="M16 7 L23 10 L23 18 Q23 23 16 26 Q9 23 9 18 L9 10 Z" fill="rgba(0,0,0,0.15)"/>
      {emblem === "cross"  && <><line x1="16" y1="10" x2="16" y2="24" stroke="rgba(255,255,255,0.35)" strokeWidth="2"/><line x1="10" y1="17" x2="22" y2="17" stroke="rgba(255,255,255,0.35)" strokeWidth="2"/></>}
      {emblem === "gem"    && <circle cx="16" cy="17" r="4" fill="rgba(255,255,255,0.25)" stroke="rgba(255,255,255,0.4)" strokeWidth="1"/>}
      {emblem === "rune"   && <path d="M13 11 L16 8 L19 11 L17 16 L16 17 L15 16 Z" fill="rgba(255,255,255,0.3)"/>}
      {emblem === "sun"    && <circle cx="16" cy="17" r="3" fill="#f59e0b" opacity="0.8"/>}
      {glow && <path d="M16 4 L26 8 L26 18 Q26 26 16 29 Q6 26 6 18 L6 8 Z" fill={glow} opacity="0.2"/>}
    </svg>
  );
}

function PotionIcon({liquid, size="md", sparkle=false}) {
  const h = size==="lg" ? 5 : size==="sm" ? 8 : 7;
  return (
    <svg viewBox="0 0 32 32" width="28" height="28">
      <rect x="13" y={h-2} width="6" height="4" rx="1" fill="#aaa" stroke="#777" strokeWidth="1"/>
      <line x1="14" y1={h-2} x2="18" y2={h-2} stroke="#ccc" strokeWidth="1"/>
      <path d={`M11 ${h+2} L9 22 Q9 28 16 28 Q23 28 23 22 L21 ${h+2} Z`} fill="#111" stroke="rgba(0,0,0,0.5)" strokeWidth="1.2"/>
      <path d={`M11 ${h+2} L9 22 Q9 28 16 28 Q23 28 23 22 L21 ${h+2} Z`} fill={liquid} opacity="0.65"/>
      <ellipse cx="16" cy="22" rx="5" ry="3" fill={liquid} opacity="0.4"/>
      {sparkle && <>
        <circle cx="12" cy="17" r="1" fill="rgba(255,255,255,0.6)"/>
        <circle cx="20" cy="20" r="0.8" fill="rgba(255,255,255,0.5)"/>
      </>}
    </svg>
  );
}

function WeaponSword({blade="#ccc", guard="#888", grip="#6a4a2a", tip=null}) {
  return (
    <svg viewBox="0 0 32 32" width="28" height="28">
      <rect x="15" y="3" width="3" height="20" rx="1" fill={blade} stroke="rgba(0,0,0,0.3)" strokeWidth="1"/>
      <polygon points="16.5,3 14,7 19,7" fill={tip||blade}/>
      <line x1="8" y1="20" x2="25" y2="20" stroke={guard} strokeWidth="3" strokeLinecap="round"/>
      <rect x="14.5" y="20" width="4" height="8" rx="1.5" fill={grip}/>
      <line x1="15.2" y1="6" x2="17.2" y2="17" stroke="rgba(255,255,255,0.25)" strokeWidth="1"/>
    </svg>
  );
}

function WeaponDagger({blade="#ccc", guard="#888", grip="#3a2a1a"}) {
  return (
    <svg viewBox="0 0 32 32" width="28" height="28">
      <rect x="15.5" y="4" width="2.5" height="17" rx="0.8" fill={blade} stroke="rgba(0,0,0,0.3)" strokeWidth="1"/>
      <polygon points="16.75,4 14.5,9 19,9" fill={blade}/>
      <line x1="11" y1="19" x2="22" y2="19" stroke={guard} strokeWidth="2.5" strokeLinecap="round"/>
      <rect x="15" y="19" width="3.5" height="7" rx="1.5" fill={grip}/>
      <line x1="16" y1="7" x2="17.5" y2="16" stroke="rgba(255,255,255,0.3)" strokeWidth="0.8"/>
    </svg>
  );
}

function WeaponAxe({head="#9a9aaa", shaft="#6a4a2a"}) {
  return (
    <svg viewBox="0 0 32 32" width="28" height="28">
      <rect x="15" y="10" width="3" height="20" rx="1" fill={shaft} stroke="rgba(0,0,0,0.3)" strokeWidth="1"/>
      <path d="M6 6 Q6 3 16 3 Q21 5 21 12 Q16 9 6 13 Z" fill={head} stroke="rgba(0,0,0,0.3)" strokeWidth="1.5"/>
      <line x1="8" y1="7" x2="18" y2="11" stroke="rgba(255,255,255,0.2)" strokeWidth="1.2"/>
    </svg>
  );
}

function WeaponWand({orb="#ff6600", shaft="#5a3010"}) {
  return (
    <svg viewBox="0 0 32 32" width="28" height="28">
      <rect x="15" y="13" width="3" height="17" rx="1.5" fill={shaft} stroke="rgba(0,0,0,0.3)" strokeWidth="1"/>
      <circle cx="16.5" cy="10" r="6" fill="#111" stroke={orb} strokeWidth="1.8"/>
      <circle cx="16.5" cy="10" r="3.5" fill={orb} opacity="0.8"/>
      <circle cx="15.2" cy="8.5" r="1.2" fill="rgba(255,255,255,0.4)"/>
    </svg>
  );
}

function WeaponStaff({crystal="#88ccff", shaft="#2a3a5a"}) {
  return (
    <svg viewBox="0 0 32 32" width="28" height="28">
      <rect x="15" y="14" width="3" height="16" rx="1.5" fill={shaft} stroke="#4a6aaa" strokeWidth="1"/>
      <path d="M11 11 L16.5 3 L22 11 L19 13 L16.5 7 L14 13 Z" fill={shaft} stroke="#4a9eff" strokeWidth="1.5"/>
      <circle cx="16.5" cy="7" r="3" fill={crystal}/>
      <circle cx="15.5" cy="6" r="1.2" fill="rgba(255,255,255,0.5)"/>
    </svg>
  );
}

function WeaponBow({color="#f59e0b"}) {
  return (
    <svg viewBox="0 0 32 32" width="28" height="28">
      <path d="M8 4 Q3 16 8 28" stroke={color} strokeWidth="3" fill="none" strokeLinecap="round"/>
      <path d="M8 4 Q5 16 8 28" stroke="rgba(0,0,0,0.3)" strokeWidth="1.5" fill="none"/>
      <line x1="8" y1="4" x2="8" y2="28" stroke="#777" strokeWidth="1" strokeDasharray="3,2"/>
      <line x1="8" y1="16" x2="26" y2="16" stroke="#999" strokeWidth="1.2"/>
      <polygon points="24,14 28,16 24,18" fill="#bbb"/>
    </svg>
  );
}

function RelicIcon({border="#ff4d4d", inner}) {
  return (
    <svg viewBox="0 0 32 32" width="28" height="28">
      <polygon points="16,3 25,12 16,29 7,12" fill="#0d0a14" stroke={border} strokeWidth="2"/>
      <polygon points="16,3 25,12 16,17 7,12" fill="rgba(0,0,0,0.3)" stroke={border} strokeWidth="0.8" opacity="0.5"/>
      {inner}
    </svg>
  );
}

